// /frontend-react/src/components/ProfilePage.js (FINAL CSS POLISH)

import React from 'react';
import HeaderBar from './HeaderBar';

// --- Local Mock Profile Data (remains the same) ---
const mockProfileData = { /* ... */ };

function ProfilePage({ isEasyMode, goToPage, onMenuClick }) {
    const profile = mockProfileData;

    // --- REVISED InfoCard Component for MAX CLEANLINESS ---
    const InfoCard = ({ title, value }) => (
        <div style={{
            padding: '25px', // More vertical spacing
            margin: '8px 0', // Less vertical margin, rely on padding
            width: '100%',
            backgroundColor: '#fff',
            border: 'none', // Removed unnecessary border
            borderBottom: '1px solid #e0e0e0', // Very light, clean separator
            textAlign: 'left',
            boxShadow: 'none', // Removed shadow for flat, modern look
        }}>
            {/* Title (Label) - Muted color, clean font */}
            <p style={{ 
                fontSize: isEasyMode ? '22px' : '15px', 
                fontWeight: '600', 
                margin: '0 0 5px 0', 
                color: '#6c757d' 
            }}>
                {title.toUpperCase()}
            </p>
            
            {/* Value (Actual Data) - Large and prominent */}
            <p style={{ 
                fontSize: isEasyMode ? '34px' : '22px', 
                fontWeight: 'bold',
                margin: 0, 
                color: '#333' 
            }}>
                {value}
            </p>
        </div>
    );
    // --- END REVISED InfoCard ---

    return (
        <div style={{ padding: '0 0 20px 0', textAlign: 'center' }}>
            <HeaderBar
                title="Profile"
                onBackClick={() => goToPage('dashboard')}
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '30px 0 20px 0', color: '#333' }}>
                Personal Details
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%', padding: '0 10px' }}>
                <InfoCard title="Name" value={profile.name} isEasyMode={isEasyMode}/>
                <InfoCard title="IC Number" value={profile.icNumber} isEasyMode={isEasyMode}/>
                <InfoCard title="Date of Birth" value={profile.dateOfBirth} isEasyMode={isEasyMode}/>
                <InfoCard title="Address" value={profile.address} isEasyMode={isEasyMode}/>
                <InfoCard title="Emergency Contact" value={profile.emergencyContact} isEasyMode={isEasyMode}/>

                <button
                    onClick={() => alert("Redirecting to Edit Profile.")}
                    style={{
                        padding: '18px 35px', // Larger button
                        fontSize: isEasyMode ? '30px' : '20px', 
                        backgroundColor: 'orange',
                        color: 'white',
                        border: 'none',
                        borderRadius: '10px',
                        marginTop: '40px'
                    }}
                >
                    EDIT PROFILE ✍️
                </button>
            </div>
        </div>
    );
}

export default ProfilePage;
